import hashlib,json,subprocess
from pathlib import Path
r=Path('.local/holdout-cleanarchitecture').resolve();out=r/'readiness';dest=r/'capture-input/CleanArchitecture';dest.parent.mkdir(exist_ok=True)
subprocess.run(['git','clone','--no-hardlinks',str(r/'source'),str(dest)],check=True)
subprocess.run(['git','-C',str(dest),'remote','set-url','origin','https://github.com/jasontaylordev/CleanArchitecture.git'],check=True)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
base=Path('research/semantic-intelligence/results/holdout-cleanarchitecture-20261002').resolve()
manifest=json.loads((base/'source-manifest.json').read_text())
for f in manifest['files']:assert sha(dest/f['path'])==f['sha256']
moe=Path('.local/compact-discovery/moedex').resolve();worker=r/'worker-source/bin/Debug/net10.0/Moedex.SemanticWorker.dll'
args=[str(moe),'semantic','capture','--checkout',str(dest),'--commit',manifest['commit'],'--origin',manifest['repository']+'.git','--repo','CleanArchitecture','--project','src/Web/Web.csproj','--framework','net10.0','--configuration','Debug','--dotnet',str(r/'dotnet/dotnet'),'--sdk-path',str(r/'dotnet/sdk/10.0.401'),'--worker',str(worker),'--workspace',str(r/'capture/workspace'),'--output',str(r/'capture/project.semantic'),'--dependency-bundle',str(r/'bundle'),'--restore-offline','--restore-standard-evaluation','--timeout','8m']
plan={'status':'prepared, not executed; independent oracle review required first','source_commit':manifest['commit'],'namespace':'CleanArchitecture','capture_argv':args,'expected_project_closure':[p['project'] for p in json.loads((out/'build-inputs.json').read_text())['projects']],'required_source_hashes':{f['path']:f['sha256'] for f in manifest['files']},'frozen_inputs':{str(p):sha(p) for p in [moe,worker,r/'dotnet/dotnet',r/'bundle/manifest.json',base/'source-gold.json',base/'protocol.json',Path('research/semantic-intelligence/agent-journeys/client.py').resolve(),Path('research/semantic-intelligence/agent-journeys/browse.py').resolve()]},'capture_acceptance':['Require complete contexts; verify exact six-project closure and all gold evidence source hashes','Fail closed on missing source or incomplete compilation; retain logs and do not tune detectors','Hash post-review source gold separately before capture; retain original and review amendments','Only after oracle freeze may product artifact outputs be inspected','Publish from same pinned commit; freeze index and native catalog before solvers','Collect catalog via native tools/list; serve with --embed none'],'execution_approval':'Pending: current user instruction prohibits subagents. Proposed exception is one fresh agent at a time: one oracle reviewer, six solvers, six answer reviewers. No concurrent agents.'}
(out/'launch-plan.json').write_text(json.dumps(plan,indent=2)+'\n')
prompt=f'''You are the independent source-oracle reviewer for the CleanArchitecture holdout. Work alone; do not delegate. Do not query Moedex or CodeGraph, read their outputs, or inspect implementation.\n\nRead the six task prompts and 30 atoms in {base/'source-gold.json'}, the protocol at {base/'protocol.json'}, and checked-in source under {dest}. Verify commit {manifest['commit']} and cited file hashes against {base/'source-manifest.json'}. You may inspect other tracked source in that repository to challenge omissions or ambiguity. Do not run the application.\n\nReview each atom for factual support, exact citation ranges, task relevance, consistent partial-credit criteria and overbroad negative/runtime claims. The executed variant will be Debug/net10.0, no custom DefineConstants (default SQLite branch); prompts asking provider alternatives should still recognize inactive checked-in branches. SDK10.0.401 build succeeds with nine transitive package compatibility warnings.\n\nReturn JSON with keys review_status (accept or amend), atom_reviews (one entry for each atom: id, verdict, reason, suggested_requirement, suggested_citations), task_scope_issues, missing_material_atoms, independence_attestation. Quote only source needed to explain findings. Propose corrections before any product query; do not infer native product capability. Your output is review evidence, not a solver answer or competitive result.\n'''
(out/'oracle-review-prompt.txt').write_text(prompt)
print('Prepared unexecuted capture plan and source-only reviewer assignment')
